.expandable-panel {
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 1rem 1.25rem;
    background: #f7fafc;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 600;
    color: #2d3748;
}

.panel-header:hover {
    background: #edf2f7;
}

.expand-icon {
    font-size: 0.75rem;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e2e8f0;
}

.tfa-section {
    margin-bottom: 1.5rem;
    padding: 1rem 1.25rem;
    background: #f7fafc;
    border-radius: 8px;
}

.tfa-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.tfa-row h3 {
    margin: 0 0 0.25rem 0;
    font-size: 1rem;
}

.tfa-status {
    margin: 0;
    font-size: 0.9rem;
    color: #718096;
}

.status-enabled {
    color: #38a169;
    font-weight: 600;
}

.status-disabled {
    color: #e53e3e;
    font-weight: 600;
}

.last-change {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #718096;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #cbd5e0;
    border-radius: 26px;
    transition: 0.3s;
}

.toggle-slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    border-radius: 50%;
    transition: 0.3s;
}

.toggle-switch input:checked + .toggle-slider {
    background-color: #2b6cb0;
}

.toggle-switch input:checked + .toggle-slider::before {
    transform: translateX(22px);
}

.sessions-section {
    margin-bottom: 1.5rem;
}

.sessions-section h3 {
    margin-bottom: 0.75rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e2e8f0;
}

.sessions-table th {
    font-weight: 600;
    color: #4a5568;
    font-size: 0.85rem;
    text-transform: uppercase;
}

.btn-danger-sm {
    padding: 0.3rem 0.75rem;
    background: #fed7d7;
    color: #c53030;
    border: 1px solid #fc8181;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-danger-sm:hover {
    background: #fc8181;
    color: white;
}

.current-badge {
    font-size: 0.8rem;
    padding: 0.2rem 0.5rem;
    background: #c6f6d5;
    color: #276749;
    border-radius: 4px;
}

.dialog-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 12px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.dialog h3 {
    margin: 0 0 0.75rem 0;
}

.dialog p {
    color: #4a5568;
    margin-bottom: 1.25rem;
}

.dialog-buttons {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

.btn-danger {
    padding: 0.5rem 1rem;
    background: #e53e3e;
    color: white;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 500;
}

.btn-danger:hover {
    background: #c53030;
}

