toolArgs.file_text:
@namespace sv_127f78f44fa84b6797e4e0a4463a4519.Components.Pages.Settings
@using sv_127f78f44fa84b6797e4e0a4463a4519.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme Selector -->
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-option">
                        <input type="radio" name="theme" value="Light"
                               checked="@(_theme == "Light")"
                               @onchange="() => _theme = &quot;Light&quot;" />
                        <span>☀️ Light</span>
                    </label>
                    <label class="radio-option">
                        <input type="radio" name="theme" value="Dark"
                               checked="@(_theme == "Dark")"
                               @onchange="() => _theme = &quot;Dark&quot;" />
                        <span>🌙 Dark</span>
                    </label>
                    <label class="radio-option">
                        <input type="radio" name="theme" value="System"
                               checked="@(_theme == "System")"
                               @onchange="() => _theme = &quot;System&quot;" />
                        <span>💻 System</span>
                    </label>
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label class="radio-option">
                        <input type="radio" name="fontSize" value="Small"
                               checked="@(_fontSize == "Small")"
                               @onchange="() => _fontSize = &quot;Small&quot;" />
                        <span>Small</span>
                    </label>
                    <label class="radio-option">
                        <input type="radio" name="fontSize" value="Medium"
                               checked="@(_fontSize == "Medium")"
                               @onchange="() => _fontSize = &quot;Medium&quot;" />
                        <span>Medium</span>
                    </label>
                    <label class="radio-option">
                        <input type="radio" name="fontSize" value="Large"
                               checked="@(_fontSize == "Large")"
                               @onchange="() => _fontSize = &quot;Large&quot;" />
                        <span>Large</span>
                    </label>
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_language">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="form-group">
                <label class="toggle-row">
                    <span>Compact Mode</span>
                    <input type="checkbox" @bind="_compactMode" />
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p>This is how your content will appear with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Here is some example text showing the selected theme and font size.</p>
                </div>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAsync">Save</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Appearance settings saved!</div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var theme = _theme.ToLowerInvariant();
        var size = _fontSize.ToLowerInvariant();
        var compact = _compactMode ? "compact" : "";
        return $"preview-{theme} preview-{size} {compact}".Trim();
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.radio-group {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    cursor: pointer;
    transition: border-color 0.15s, background 0.15s;
}

.radio-option:hover {
    border-color: #2b6cb0;
    background: #ebf8ff;
}

.radio-option input[type="radio"] {
    accent-color: #2b6cb0;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #f7fafc;
    border-radius: 8px;
    cursor: pointer;
}

.toggle-row input[type="checkbox"] {
    width: 1.25rem;
    height: 1.25rem;
    accent-color: #2b6cb0;
}

.preview-area {
    margin: 1.5rem 0;
    padding: 1.5rem;
    border: 2px dashed #e2e8f0;
    border-radius: 12px;
    transition: all 0.3s;
